import { Injectable } from '@angular/core';
import { style } from '@primeuix/styles/compare';
import { BaseStyle } from 'primeng/base';

const classes = {
    root: 'p-compare p-component',
    item: 'p-compare-item',
    handle: ({ instance }: any) => ['p-compare-handle', { 'p-disabled': instance.pcCompare?.disabled() }],
    indicator: ({ instance }: any) => ['p-compare-indicator', { 'p-disabled': instance.pcCompare?.disabled() }],
    input: 'p-compare-input'
};

@Injectable()
export class CompareStyle extends BaseStyle {
    name = 'compare';

    style = style;

    classes = classes;
}

/**
 *
 * Compare allows comparing two items side by side with a slider.
 *
 * [Live Demo](https://www.primeng.org/compare)
 *
 * @module comparestyle
 *
 */
export enum CompareClasses {
    /**
     * Class name of the root element
     */
    root = 'p-compare',
    /**
     * Class name of the item element
     */
    item = 'p-compare-item',
    /**
     * Class name of the handle element
     */
    handle = 'p-compare-handle',
    /**
     * Class name of the indicator element
     */
    indicator = 'p-compare-indicator',
    /**
     * Class name of the input element
     */
    input = 'p-compare-input'
}

export interface CompareStyle extends BaseStyle {}
